// Pseudo: gate checks before OpenAI call
function shouldFallback(prompt, budget, policy) {
  if (policy.violationDetected) return true;
  if (estimateCost(prompt) > budget) return true;
  if (promptContainsPII(prompt)) return true;
  return false;
}
```

